import {scenarios,agents,makeRun,metrics,validate,editQuantity,revalidate,approve,chooseAlternative} from './model.js';
const paths={shield:'M12 3 4 6v6c0 5 8 9 8 9s8-4 8-9V6L12 3Z M8 12l3 3 5-6',grid:'M3 3h7v7H3z M14 3h7v7h-7z M3 14h7v7H3z M14 14h7v7h-7z',network:'M9 3h6v5H9z M2 16h6v5H2z M16 16h6v5h-6z M12 8v4 M5 16v-4h14v4',flask:'M9 3h6 M10 3v7L4 19c-.6 1 .2 2 1 2h14c.8 0 1.6-1 1-2l-6-9V3 M7 15h10',chart:'M4 3v17h17 M8 15v-5 M13 15V6 M18 15v-8',history:'M3 11a9 9 0 1 1 2 7 M3 4v7h7 M12 7v5l3 2',book:'M4 4h6l2 2 2-2h6v16h-6l-2 1-2-1H4z M12 6v15',settings:'M12 8a4 4 0 1 0 0 8 4 4 0 0 0 0-8 M12 2v3 M12 19v3 M2 12h3 M19 12h3 M5 5l2 2 M17 17l2 2 M5 19l2-2 M17 7l2-2',chevron:'m9 5 7 7-7 7',down:'m6 9 6 6 6-6',arrow:'M4 12h16 m-6-6 6 6-6 6',download:'M12 3v12 m-5-5 5 5 5-5 M4 16v5h16v-5',play:'m8 4 12 8-12 8V4Z',bell:'M5 17h14l-2-3V9a5 5 0 0 0-10 0v5l-2 3Z M10 21h4',help:'M9 9a3 3 0 1 1 5 2l-2 2v1 M12 17h.01 M21 12a9 9 0 1 1-18 0 9 9 0 0 1 18 0',alert:'m12 3 10 18H2L12 3Z M12 9v5 M12 17h.01',clock:'M12 7v5l3 2 M21 12a9 9 0 1 1-18 0 9 9 0 0 1 18 0',box:'m12 3 9 5v9l-9 5-9-5V8l9-5Z M3 8l9 5 9-5 M12 13v9 M8 5l9 5',truck:'M2 5h12v12H2z M14 9h4l4 5v3h-8 M6 21a2 2 0 1 0 0-4 2 2 0 0 0 0 4 M18 21a2 2 0 1 0 0-4 2 2 0 0 0 0 4',factory:'M3 21V9l6 3V6l6 4V3h4v18H3Z M7 16h1 M12 16h1 M17 16h1',warehouse:'M3 21V8l9-5 9 5v13 M7 21V11h10v10 M7 16h10',check:'m5 12 4 4L19 6',circlecheck:'M21 12a9 9 0 1 1-18 0 9 9 0 0 1 18 0 M8 12l3 3 5-6',shuffle:'M3 6h3c4 0 8 12 12 12h3 M3 18h3c4 0 8-12 12-12h3 m-4-4 4 4-4 4 m0 4 4 4-4 4',arrows:'M3 7h17 m-4-4 4 4-4 4 M21 17H4 m4-4-4 4 4 4',calendar:'M4 5h16v16H4z M8 3v4 M16 3v4 M4 10h16 M8 14h3 M8 17h6',spark:'m12 3 2.5 6.5L21 12l-6.5 2.5L12 21l-2.5-6.5L3 12l6.5-2.5L12 3Z',lock:'M5 10h14v11H5z M8 10V6a4 4 0 0 1 8 0v4 M12 14v3',money:'M3 5h18v14H3z M15 12a3 3 0 1 1-6 0 3 3 0 0 1 6 0 M6 12h.01 M18 12h.01',close:'m6 6 12 12 M18 6 6 18',info:'M12 11v6 M12 7h.01 M21 12a9 9 0 1 1-18 0 9 9 0 0 1 18 0',refresh:'M20 10a8 8 0 0 0-14-5L3 8 M3 3v5h5 M4 14a8 8 0 0 0 14 5l3-3 M21 21v-5h-5',menu:'M3 6h18 M3 12h18 M3 18h18',user:'M16 7a4 4 0 1 1-8 0 4 4 0 0 1 8 0 M4 21v-2a8 6 0 0 1 16 0v2',eye:'M2 12s4-7 10-7 10 7 10 7-4 7-10 7S2 12 2 12Z M15 12a3 3 0 1 1-6 0 3 3 0 0 1 6 0'};
const icon=(name,cls='')=>`<svg class="icon ${cls}" viewBox="0 0 24 24" aria-hidden="true"><path d="${paths[name]||paths.box}"/></svg>`;
const esc=s=>String(s).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const money=n=>new Intl.NumberFormat('en-US',{style:'currency',currency:'USD',maximumFractionDigits:0}).format(n);
const shortMoney=n=>`$${(n/1000).toFixed(1)}k`;
let page='overview',config={scenario:'SC1',seed:42},run=makeRun(config),running=false,stage=4,runCounter=1,history=[],authMode='signup',authenticated=false;
try{const stored=JSON.parse(localStorage.getItem('flowstate-decisions')||localStorage.getItem('supplyshield-decisions')||'[]');if(Array.isArray(stored))history=stored.filter(x=>x&&typeof x.actor==='string'&&typeof x.time==='string'&&Array.isArray(x.actions));authenticated=sessionStorage.getItem('flowstate-authenticated')==='true';}catch{}
const closed=()=>['APPROVED','APPROVED_WITH_EDITS','REJECTED'].includes(run.status);
const app=document.querySelector('#app'),modal=document.querySelector('#modal');
const navs=[['overview','grid','Control room'],['scenarios','flask','Scenario lab'],['network','network','Supply network'],['comparison','chart','Planner comparison'],['audit','history','Decision log']];
function authView(){return `<main class="auth-shell"><section class="auth-card"><div class="auth-form"><div class="auth-brand"><span class="brand-mark">${icon('spark')}</span><span>flowstate</span></div><div class="auth-heading"><div class="eyebrow">RESILIENT OPERATIONS WORKSPACE</div><h1>${authMode==='signup'?'Create an account':'Welcome back'}</h1><p>${authMode==='signup'?'Brainstorm in chat, build in flowstate':'Sign in to review your supply chain decisions'}</p></div><div class="social-grid"><button class="social-btn" data-action="auth-google"><span class="google-g">G</span>${authMode==='signup'?'Sign up':'Continue'} with Google</button><button class="social-btn" data-action="auth-apple">${icon('apple')} ${authMode==='signup'?'Sign up':'Continue'} with Apple</button></div><div class="auth-divider"><span>or</span></div><form id="auth-form" class="auth-fields">${authMode==='signup'?`<div class="auth-row"><label><span>First Name</span><input name="firstName" type="text" placeholder="Harshit" autocomplete="given-name" required></label><label><span>Last Name</span><input name="lastName" type="text" placeholder="Sharma" autocomplete="family-name" required></label></div>`:''}<label><span>Email</span><input name="email" type="email" placeholder="you@company.com" autocomplete="email" required></label><label><span>Password</span><input name="password" type="password" placeholder="At least 6 characters" minlength="6" autocomplete="${authMode==='signup'?'new-password':'current-password'}" required></label>${authMode==='signup'?`<div class="auth-checks"><label class="auth-check"><input type="checkbox" name="updates"><span>I don't want to receive emails about flowstate feature updates</span></label><label class="auth-check"><input type="checkbox" name="terms" required><span>By creating an account, you agree to our <a href="#" data-action="terms">Terms and Services</a> and <a href="#" data-action="privacy">Privacy Policy</a></span></label></div>`:''}<button class="auth-submit" type="submit">${authMode==='signup'?'Create account':'Sign in'} ${icon('arrow')}</button></form><p class="auth-switch">${authMode==='signup'?'Already have an account?':'Need an account?'} <button data-action="auth-toggle">${authMode==='signup'?'Sign in':'Create one'}</button></p><p class="auth-demo">Demo login only · no credentials leave this browser.</p></div><aside class="auth-art"><div class="art-glow"></div><div class="art-content"><div class="art-kicker">FLOWSTATE / 01</div><h2>Think clearly.<br><em>Move resiliently.</em></h2><p>A human-led control room for the moments your supply chain needs a better next move.</p><div class="art-stat"><strong>4</strong><span>specialist agents<br>working in concert</span></div><div class="art-orbit orbit-one"></div><div class="art-orbit orbit-two"></div></div><div class="art-footer"><span>${icon('lock')} Built for accountable decisions</span><span>© 2026 flowstate</span></div></aside></section></main>`}
function shell(){return `<div class="overlay" data-action="menu"></div><aside class="sidebar"><a class="brand" href="#overview" aria-label="flowstate home"><span class="brand-mark">${icon('spark')}</span>flowstate<span style="color:#9eaaa4;font-size:11px;margin-left:-7px">®</span></a><div class="workspace"><span class="workspace-icon">${icon('factory')}</span><div><strong>Manufacturing workspace</strong><small>Resilience operations</small></div></div><div class="nav-label">WORKSPACE</div><nav class="nav" aria-label="Main navigation">${navs.map(([id,i,label])=>`<button data-page="${id}" class="${page===id?'active':''}" ${page===id?'aria-current="page"':''}>${icon(i)}${label}${id==='audit'&&history.length?`<span class="count">${history.length}</span>`:''}</button>`).join('')}</nav><div class="nav-separator"></div><div class="nav-label">RESOURCES</div><nav class="nav"><button data-action="guide">${icon('book')}Demo guide</button><button data-action="assumptions">${icon('settings')}Model assumptions</button></nav><div class="sidebar-bottom"><div class="sandbox-card"><strong><span class="status-dot"></span>A safe space to plan</strong><p>Explore disruption scenarios with a reproducible demo network.</p><button data-action="guide">Explore the demo <span aria-hidden="true">↗</span></button></div><div class="profile"><span class="avatar">PS</span><div><strong>Priya Sharma</strong><p>Supply planner · flowstate demo</p></div></div></div></aside><main class="main"><header class="topbar"><div class="breadcrumb"><button class="menu-toggle" data-action="menu" aria-label="Open navigation">${icon('menu')}</button><span>Workspace</span><span>/</span><strong>${navs.find(n=>n[0]===page)?.[2]}</strong></div><div class="top-right"><span><span class="status-dot"></span>Workspace ready</span><span class="demo-pill">Demo data</span><button class="icon-button" data-action="alerts" aria-label="View disruption alerts">${icon('bell')}</button><button data-action="guide" aria-label="Help">${icon('help')}</button></div></header><div class="content">${heading()}${page==='overview'?overview():page==='scenarios'?scenarioPage():page==='network'?networkPage():page==='comparison'?comparisonPage():auditPage()}<footer class="footer"><span>${icon('lock')}Human decisions. Agent intelligence. Resilient operations.</span><span>Synthetic demo · Seed ${run.config.seed} · 60-day horizon</span></footer></div></main>`}
function heading(){const copy={overview:['Your supply chain, one step ahead.','Monitor disruptions, coordinate agents, and keep your network moving.'],scenarios:['Explore the unexpected.','Test a disruption and see how your recovery options change.'],network:['Every connection matters.','A three-echelon view of your manufacturing network.'],comparison:['Decisions, backed by perspective.','Compare three planning approaches on the same scenario and seed.'],audit:['A clear trail of every decision.','Review who approved what, and the exact plan version behind it.']}[page];return `<section class="page-heading"><div><div class="eyebrow">${page==='overview'?'SUPPLY CHAIN CONTROL ROOM':navs.find(n=>n[0]===page)[2].toUpperCase()}</div><h1>${copy[0]}</h1><p>${copy[1]}</p></div><div class="heading-actions"><button class="btn" data-action="export">${icon('download')}Export ${page==='audit'?'log':'report'}</button><button class="btn primary" data-page="scenarios">${icon('flask')}New scenario</button></div></section>`}
function strip(){return `<div class="scenario-strip"><div class="select-wrap"><label for="scenario">ACTIVE SCENARIO</label><select id="scenario" ${running?'disabled':''}>${scenarios.map(s=>`<option value="${s.id}" ${config.scenario===s.id?'selected':''}>${s.id} · ${s.name}</option>`).join('')}</select></div><div class="scenario-meta day"><label>DISRUPTION</label><strong>Day 10–16</strong></div><div class="scenario-meta horizon"><label>HORIZON</label><strong>60 days</strong></div><div class="scenario-meta seed"><label for="seed">RANDOM SEED</label><input class="seed-input" id="seed" type="number" min="1" max="99999" step="1" value="${config.seed}" ${running?'disabled':''}></div><button class="btn primary" data-action="run" ${running?'disabled':''}>${icon(running?'refresh':'play',running?'spinner':'')}${running?'Simulating…':'Run scenario'}</button></div>`}
function alert(){return `<div class="alert"><div class="alert-icon">${icon('alert')}</div><div class="alert-copy"><div class="alert-title">Critical supplier disruption detected <span class="tag orange">High impact</span></div><p>S1 · Apex Components is offline for 7 days. 3 SKUs and 2 plants are exposed.${run.scenario.stale?' Inventory snapshot is 24 hours stale.':''}</p></div><button class="text-btn" data-action="exposure">View impact ${icon('arrow')}</button></div>`}
function metricCards(){const m=metrics(run),r=metrics(run,'rules');const items=[['Projected fill rate',m.fill.toFixed(1),'%','+'+(m.fill-r.fill).toFixed(1)+' pts','vs. reorder rules','box'],['Total landed cost',shortMoney(m.cost),'',((1-m.cost/r.cost)*100).toFixed(1)+'% lower','vs. reorder rules','money'],['Recovery time',m.recovery,'days',(r.recovery-m.recovery)+' days faster','vs. reorder rules','clock'],['Hard constraint checks',validate(run).filter(c=>c.pass).length+'/6','','Demo checks','pass locally','shield']];return `<div class="metrics">${items.map((m,i)=>`<div class="metric"><div class="metric-label">${m[0]}${icon(m[5])}</div><div class="metric-value">${m[1]}<small>${m[2]}</small></div><div class="metric-foot"><b>${m[3]}</b><span>${m[4]}</span></div><svg class="mini-spark" viewBox="0 0 85 35" aria-hidden="true"><path d="${i===1?'M1 6 13 11 23 8 35 17 46 15 57 23 68 21 84 30':i===3?'M1 23 20 23 23 19 40 19 44 12 62 12 65 8 84 8':'M1 29 12 24 22 27 34 17 45 20 55 10 67 14 84 4'}" fill="none" stroke="#82b89b" stroke-width="1.4"/></svg></div>`).join('')}</div>`}
const nodes=[['S1','Apex Components','Offline · 7 days',15,23,'factory','down'],['S2','Nexa Supply','Qualified alternate',15,44,'factory','alt'],['S3','Vertex Industrial','Available',15,65,'factory',''],['S4','Orion Materials','Available',15,86,'factory',''],['P1','North plant','72% utilisation',50,37,'factory',''],['P2','South plant','64% utilisation',50,73,'factory',''],['D1','North DC','3.2 days cover',85,20,'warehouse',''],['D2','East DC','4.1 days cover',85,37,'warehouse',''],['D3','Central DC','12.4 days cover',85,54,'warehouse',''],['D4','West DC','8.6 days cover',85,71,'warehouse',''],['D5','South DC','9.1 days cover',85,88,'warehouse','']];
function network(full=false){const lines=[[15,23,50,37,'route-down'],[15,23,50,73,'route-down'],[15,44,50,37,'route-alt'],[15,65,50,37,''],[15,65,50,73,'route-active'],[15,86,50,73,''],[50,37,85,20,'route-active'],[50,37,85,37,'route-active'],[50,37,85,54,''],[50,73,85,54,''],[50,73,85,71,'route-active'],[50,73,85,88,'route-active']];return `<section class="panel ${full?'full-network':''}"><div class="panel-head"><div><h2>Network overview <span class="tag">11 nodes</span></h2><p>Your three-echelon network at a glance</p></div><div class="legend"><span><i></i>Operational</span><span><i class="red"></i>Disrupted</span><span><i class="dashed"></i>Alternate</span></div></div><div class="network-map"><svg class="network-svg" viewBox="0 0 100 100" preserveAspectRatio="none" aria-hidden="true">${lines.map(([x,y,xx,yy,c])=>`<path vector-effect="non-scaling-stroke" class="${c}" d="M${x} ${y} C${(x+xx)/2} ${y},${(x+xx)/2} ${yy},${xx} ${yy}"/>`).join('')}</svg>${['SUPPLIERS','MANUFACTURING','DISTRIBUTION'].map((n,i)=>`<span class="echelon-label" style="left:${15+i*35}%">${n}</span>`).join('')}${nodes.map(n=>`<button class="node ${n[6]}" style="left:${n[3]}%;top:${n[4]}%" data-node="${n[0]}" aria-label="${n[0]} ${n[1]}, ${n[2]}"><span class="node-icon">${icon(n[5])}</span><span><strong>${n[0]} · ${n[1].replace(' Components','').replace(' Supply','').replace(' Industrial','').replace(' Materials','')}</strong><small>${n[2]}</small></span><i class="dot"></i></button>`).join('')}</div><div class="map-footer"><span>${icon('info')}Select a node to inspect its status</span><span>4 suppliers <b>·</b> 2 plants <b>·</b> 5 DCs</span></div></section>`}
function agentPanel(){return `<section class="panel"><div class="panel-head"><div><h2>Agent workspace</h2><p>Specialists working in coordination</p></div><span class="tag green">${running?'Running':'4 agents'}</span></div>${running?`<div class="progress-bar"><i style="width:${stage/5*100}%"></i></div>`:''}<div class="agent-list">${agents.map((a,i)=>`<button class="agent ${running&&stage===i?'running':''}" data-agent="${i}" style="text-align:left;width:100%"><span class="agent-icon ${a.color}">${icon(a.icon)}</span><span class="agent-text"><strong>${a.name} agent</strong><p>${running?(i<stage?'Analysis complete':i===stage?'Analysing scenario…':'Waiting for snapshot'):a.detail}</p></span><span class="check">${icon(running&&i>=stage?'clock':'circlecheck')}</span></button>`).join('')}</div><div class="coordinator"><span class="agent-icon">${icon('spark')}</span><div><strong>Coordinator ${running?'is reconciling':'has a plan'}</strong><p>${running?'Validating proposals and resolving conflicts…':'4 actions validated · ready for your review'}</p></div></div></section>`}
function actionTable(edit=false){return `<div class="table-scroll"><table class="${edit?'edit-table':''}"><thead><tr><th>ACTION / AGENT</th><th class="route-cell">ROUTE</th><th>QUANTITY</th><th>ARRIVAL</th><th></th></tr></thead><tbody>${run.actions.map(a=>`<tr><td><div class="action-cell">${icon(a.icon)}<div><strong>${a.type}</strong><small>${a.agent} · ${a.sku}</small></div></div></td><td class="route-cell">${a.from} → ${a.to}</td><td>${edit?`<input class="quantity" type="number" step="10" min="0" value="${a.quantity}" data-quantity="${a.id}" aria-label="${a.type} quantity" ${closed()?'disabled':''}>`:`${a.quantity} <span style="color:#9aa7ad;font-size:8px">units</span>`}</td><td style="color:#83918e">Day ${a.day}</td><td><button class="row-button" data-detail="${a.id}" aria-label="View ${a.type} rationale">${icon('chevron')}</button></td></tr>`).join('')}</tbody></table></div>`}
function planPanel(){return `<section class="panel"><div class="panel-head"><div><h2>Recommended recovery plan</h2><p>Four coordinated actions. One resilient response.</p></div><div class="plan-header-right"><span class="tag ${closed()?'green':'orange'}">${statusLabel()}</span></div></div><div class="plan-banner">${icon('spark')}Balanced service protection and recovery cost <span class="tag green">${run.confidence}% confidence</span></div>${actionTable()}<div class="plan-bottom"><span class="confidence">${icon('shield')}${validate(run).filter(c=>c.pass).length} of 6 demo checks passed</span><button class="text-btn" data-action="review">Review full plan ${icon('arrow')}</button></div></section>`}
function chart(){const m=metrics(run),base=makeRun(run.config), alternatives=['cost','balanced','service'].map(k=>{const copy=structuredClone(base);chooseAlternative(copy,k);return {k,...metrics(copy)}});const min=Math.min(...alternatives.map(a=>a.cost))-1400,max=Math.max(...alternatives.map(a=>a.cost))+1800;const x=v=>42+(v-min)/(max-min)*225;const minf=Math.min(...alternatives.map(a=>a.fill))-1.2,maxf=Math.max(...alternatives.map(a=>a.fill))+1;const y=v=>115-(v-minf)/(maxf-minf)*83;return `<div class="tradeoff"><svg viewBox="0 0 320 153" role="img" aria-label="Illustrative recovery options: higher service comes with a higher cost"><text x="4" y="12" class="chart-label">FILL RATE</text>${[40,77,114].map((yy,i)=>`<line x1="40" y1="${yy}" x2="294" y2="${yy}" stroke="#edf1ef" stroke-dasharray="3 3"/><text x="5" y="${yy+3}">${(maxf-(maxf-minf)*i/2).toFixed(0)}%</text>`).join('')}<path d="${alternatives.map((a,i)=>(i?'L':'M')+x(a.cost)+' '+y(a.fill)).join(' ')}" fill="none" stroke="#cbd9d2" stroke-dasharray="4 4"/>${alternatives.map(a=>`<circle cx="${x(a.cost)}" cy="${y(a.fill)}" r="${a.k==='balanced'?6:4}" fill="${a.k==='balanced'?'#16836b':'#b9c8bf'}"/>${a.k==='balanced'?`<circle cx="${x(a.cost)}" cy="${y(a.fill)}" r="11" stroke="#16836b" fill="none" opacity=".13"/><text x="${x(a.cost)+12}" y="${y(a.fill)-8}" style="fill:#43826b;font-size:8px">Balanced</text>`:''}`).join('')}<text x="41" y="136">${shortMoney(min)}</text><text x="144" y="136">${shortMoney((min+max)/2)}</text><text x="260" y="136">${shortMoney(max)}</text><text x="133" y="151" class="chart-label">TOTAL LANDED COST</text></svg><div class="chart-legend"><span>Alternative plans</span><span>Recommended</span></div></div>`}
function tradeoffPanel(){return `<section class="panel"><div class="panel-head"><div><h2>Service vs. cost</h2><p>Find your best recovery balance</p></div><button class="text-btn" data-action="review">Explore ${icon('arrow')}</button></div>${chart()}<div class="approval-mini"><p><strong>${closed()?'Decision recorded':'You’re in control.'}</strong>${closed()?statusLabel():'Every plan needs your approval.'}</p><button class="btn primary small" data-action="review" ${running?'disabled':''}>${icon(closed()?'eye':'check')}${closed()?'View plan':'Review plan'}</button></div></section>`}
function overview(){return `${alert()}${strip()}${config.scenario!==run.config.scenario||Number(config.seed)!==run.config.seed?'<div class="notice">Configuration changed. Run the scenario to update the results below.</div>':''}${metricCards()}<div class="main-grid">${network()}${agentPanel()}</div><div class="lower-grid">${planPanel()}${tradeoffPanel()}</div>`}
function scenarioPage(){return `<div class="info-note">${icon('info')}Choose a reproducible scenario, set a seed, and run the demo. Outcomes are illustrative frontend fixtures; no AI agents or optimisation backend are connected.</div><div class="scenario-cards">${scenarios.map(s=>`<button class="scenario-card ${s.id===config.scenario?'selected':''}" data-scenario="${s.id}"><span class="tag ${s.stale?'orange':'green'}">${s.id} · ${s.short}</span>${s.id===config.scenario?`<span class="selected-mark">${icon('circlecheck')}</span>`:''}<h3>${s.name}</h3><p>${s.description}</p><div style="margin-top:17px;color:#9aa59e;font-size:10px">7-day outage <span style="padding:0 8px">·</span> ${s.stale?'24h stale data':s.capacity===50?'50% S2 capacity':s.demand?'+20% demand':'Normal demand'}</div></button>`).join('')}</div><section class="panel"><div class="panel-head"><div><h2>Run configuration</h2><p>Shared inputs across all three planners</p></div><button class="btn primary" data-action="run" ${running?'disabled':''}>${icon(running?'refresh':'play',running?'spinner':'')}${running?'Running…':'Run scenario'}</button></div><div class="config-grid"><div><label for="lab-seed">Random seed</label><input id="lab-seed" type="number" min="1" max="99999" value="${config.seed}"></div><div><label>Shutdown window</label><input aria-label="Shutdown window" value="Day 10 to day 16 (7 days)" readonly></div><div><label>Planning horizon</label><input aria-label="Planning horizon" value="60 days · daily time buckets" readonly></div></div><div class="helper">The MVP follows the PRD: 4 suppliers, 2 plants, 5 DCs, and 6 SKUs. All scenarios use the same network and cost assumptions. Seeded values are reproducible within this frontend demo.</div></section>`}
function networkPage(){return `${alert()}${network(true)}<div class="network-stats"><section class="panel"><h3>01 · Suppliers</h3><p>S1 supplies 45% of component volume and is offline on days 10–16. S2 and S3 are qualified alternatives; S4 provides limited spot capacity.</p></section><section class="panel"><h3>02 · Manufacturing</h3><p>Two plants assemble six finished SKUs. Available production slots account for daily capacity and changeover time.</p></section><section class="panel"><h3>03 · Distribution</h3><p>Five regional DCs protect customer demand. Reallocation preserves the donor’s protected stock floor.</p></section></div>`}
function comparisonPage(){const keys=[['fill','Fill rate','%',1],['cost','Total landed cost','',0],['backorders','Backorders',' unit-days',0],['recovery','Recovery time',' days',0],['inventory','Inventory cover',' days',1],['violations','Constraint violations','',0],['runtime','Demo processing time',' s',1],['stability','Recommendation stability','%',0]];const ms=['rules','optimizer','agentic'].map(p=>metrics(run,p));return `<div class="info-note">${icon('info')}Illustrative comparison for ${run.config.scenario} · seed ${run.config.seed}. These values demonstrate the UI and are not measured benchmark results. Real evaluation requires the shared simulator and optimisation backend.</div>${strip()}<section class="panel"><div class="panel-head"><div><h2>Three planners. Identical inputs.</h2><p>${run.scenario.name} · 60-day horizon · USD</p></div><span class="tag">Demo fixtures</span></div><div class="table-scroll"><table class="comparison-table"><thead><tr><th>EVALUATION METRIC</th><th>Reorder rules<small>Independent (s, S) policy</small></th><th>Optimisation only<small>Central mathematical planner</small></th><th class="highlight">Multi-agent<small>Coordinated + human approval</small></th></tr></thead><tbody>${keys.map(([key,label,unit,dec])=>`<tr><td>${label}</td>${ms.map((m,i)=>`<td class="${i===2?'highlight':''}">${key==='cost'?money(m[key]):Number(m[key]).toLocaleString('en-US',{minimumFractionDigits:dec,maximumFractionDigits:dec})+unit}</td>`).join('')}</tr>`).join('')}</tbody></table></div><div class="helper">In this fixture, optimisation-only has a lower cost. The agentic approach adds an explanation, confidence drivers, and an explicit decision record. No winner is inferred from these sample values.</div></section>`}
function auditPage(){return `<div class="info-note">${icon('lock')}Decisions are stored in this browser for the demo. They are not an authenticated or immutable audit trail, and do not execute orders or shipments.</div><section class="panel"><div class="panel-head"><div><h2>Planner decisions <span class="tag">${history.length}</span></h2><p>Approval and rejection history</p></div><button class="btn small" data-action="export">${icon('download')}Export JSON</button></div>${history.length?`<div class="audit-list">${history.slice().reverse().map(h=>`<div class="audit-item"><span class="agent-icon ${h.decision==='REJECTED'?'amber':'green'}">${icon(h.decision==='REJECTED'?'close':'check')}</span><div><h3>${esc(h.actor)} ${h.decision==='REJECTED'?'rejected':'approved'} a recovery plan</h3><p>${esc(h.reason)}</p><div class="audit-meta">${esc(h.scenario)} · Seed ${esc(h.seed)} · Version ${esc(h.version)} · ${new Date(h.time).toLocaleString()}</div></div><span class="tag ${h.decision==='REJECTED'?'orange':'green'}">${esc(h.decision.replaceAll('_',' ').toLowerCase())}</span></div>`).join('')}</div>`:`<div class="empty">${icon('history')}<h3>Your decisions will appear here.</h3><p>Review a recovery plan and approve or reject it.<br>We’ll record the decision, version, and rationale.</p><button class="btn primary" data-action="review">Review current plan ${icon('arrow')}</button></div>`}</section>`}
function render(){
 app.innerHTML=authenticated?shell():authView();
 app.querySelectorAll('.brand-mark').forEach(mark=>{mark.classList.add('fs-logo');mark.innerHTML='<img src="assets/flowstate-logo.png" alt="Flowstate FS logo" width="40" height="42">';});
 document.title=authenticated?`flowstate · ${navs.find(n=>n[0]===page)[2]}`:`flowstate · ${authMode==='signin'?'Sign in':'Create account'}`;
 document.documentElement.classList.toggle('reduce-motion',preferences.reduceMotion);
 if(authenticated){
  app.querySelector('.top-right').innerHTML=`<button class="btn small" data-action="account-settings">${icon('settings')}Settings</button><button class="btn small" data-action="sign-out">${icon('arrow')}Sign out</button>`;
  const profile=app.querySelector('.profile');
  profile.querySelector('strong').textContent=preferences.name;
  profile.querySelector('.avatar').textContent=preferences.name.split(/\s+/).map(part=>part[0]).slice(0,2).join('').toUpperCase();
  profile.insertAdjacentHTML('beforebegin',`<nav class="nav account-nav" aria-label="Account"><button data-action="account-settings">${icon('settings')}Settings</button><button data-action="sign-out">${icon('arrow')}Sign out</button></nav>`);
 }
}
function statusLabel(){return ({PENDING_APPROVAL:'Awaiting review',DRAFT:'Needs validation',APPROVED:'Approved',APPROVED_WITH_EDITS:'Approved with edits',REJECTED:'Rejected'})[run.status]}
function toast(msg){const e=document.querySelector('#toast');e.textContent=msg;e.classList.add('show');clearTimeout(toast.timer);toast.timer=setTimeout(()=>e.classList.remove('show'),4000)}
function openModal(title,subtitle,body,foot=''){modal.innerHTML=`<div class="modal-head"><div><h2>${title}</h2><p>${subtitle}</p></div><button class="close" data-action="close" aria-label="Close dialog">${icon('close')}</button></div><div class="modal-body">${body}</div>${foot?`<div class="modal-foot">${foot}</div>`:''}`;modal.setAttribute('aria-label',title);if(!modal.open)modal.showModal();}
function review(){if(running){toast('Wait for the scenario to finish.');return;}const m=metrics(run),checks=validate(run);openModal('Your recovery plan',`${run.config.scenario} · Seed ${run.config.seed} · Version ${run.version} · ${statusLabel()}`,`${run.scenario.stale?'<div class="notice">Inventory data is 24 hours stale. Confidence is reduced; verify stock availability before acting.</div>':''}<div class="modal-metrics"><div class="modal-metric"><span>Projected fill rate</span><strong>${m.fill}%</strong></div><div class="modal-metric"><span>Total landed cost</span><strong>${money(m.cost)}</strong></div><div class="modal-metric"><span>Confidence · ${run.confidence>=80?'High':'Medium'}</span><strong>${run.confidence}%</strong></div></div><p class="rationale">Source from a qualified alternate, expedite priority stock, rebalance inventory, and reschedule production to bridge the seven-day outage.</p><details><summary>Confidence drivers & assumptions</summary><p>${run.scenario.stale?'Stale inventory reduces confidence. Stock availability needs confirmation.':'Fresh demo inventory and consistent agent proposals support this confidence fixture.'} Supplier S2 is assumed qualified, lanes available, and demand follows the selected scenario. Numeric confidence is illustrative, not calibrated.</p></details><h3>Choose a recovery balance</h3><div class="alternative-list">${[['cost','Cost-conscious','Lower spend · less protection'],['balanced','Balanced','Recommended balance'],['service','Service-first','More coverage · higher spend']].map(([k,n,d])=>`<button class="${run.alternative===k?'active':''}" data-alternative="${k}" ${closed()?'disabled':''}>${n}<small>${d}</small></button>`).join('')}</div><h3>Review actions ${closed()?'':'& edit quantities'}</h3>${actionTable(true)}${!run.validated?'<div class="notice">Quantities changed. Revalidate before approval. Plan metrics are illustrative estimates until the backend is connected.</div>':''}<h3>Constraint validation <span class="tag ${checks.every(c=>c.pass)?'green':'red'}">${checks.filter(c=>c.pass).length} / ${checks.length} passed</span></h3><div class="checks">${checks.map(c=>`<div class="constraint ${c.pass?'':'fail'}">${icon(c.pass?'circlecheck':'alert')}<div>${c.name}<small>${c.detail}</small></div></div>`).join('')}</div>${!closed()?'<div class="field"><label for="approver">Planner name</label><input id="approver" placeholder="Enter your name to record the decision" autocomplete="name"><small>Demo identity only. Approval records the plan locally and does not execute it.</small></div>':`<div class="notice good">This plan is ${statusLabel().toLowerCase()} and locked. Run a new scenario to create another plan.</div>`}`,`<button class="btn" data-action="close">Close</button><div class="btn-group">${!closed()?`<button class="btn danger" data-action="reject">Reject</button><button class="btn" data-action="validate">${icon('refresh')}Revalidate</button><button class="btn primary" data-action="approve" ${!run.validated||!checks.every(c=>c.pass)?'disabled':''}>${icon('check')}Approve plan</button>`:`<button class="btn primary" data-action="view-audit">View decision log ${icon('arrow')}</button>`}</div>`);}
function detail(id){const a=run.actions.find(a=>a.id===id);openModal(a.type,`${a.id} · ${a.agent} agent · ${a.sku}`,`<div class="modal-metrics"><div class="modal-metric"><span>Quantity</span><strong>${a.quantity} units</strong></div><div class="modal-metric"><span>Action cost</span><strong>${money(a.quantity*a.unitCost)}</strong></div><div class="modal-metric"><span>Arrival</span><strong>Day ${a.day}</strong></div></div><h3>Why this action</h3><p class="rationale">${a.rationale}</p><h3>Alternative considered</h3><p class="rationale">${a.rejected}</p><details open><summary>Evidence trail</summary><p>${a.evidence}<br>Scenario ${run.config.scenario} · seed ${run.config.seed} · demo evidence references.</p></details>`,`<button class="btn" data-action="close">Close</button><button class="btn primary" data-action="review">Back to plan ${icon('arrow')}</button>`)}
function persist(decision){history.push(decision);try{localStorage.setItem('flowstate-decisions',JSON.stringify(history));}catch{toast('Decision recorded for this session; browser storage is unavailable.');}render();}
async function runScenario(){if(running)return;const seed=Number(config.seed);if(!Number.isInteger(seed)||seed<1||seed>99999){toast('Use a whole-number seed between 1 and 99,999.');return;}running=true;stage=0;page='overview';render();for(let i=0;i<5;i++){await new Promise(r=>setTimeout(r,480));stage=i+1;render();}run=makeRun({...config,seed},++runCounter);running=false;render();toast(`${run.config.scenario} demo complete. Your plan is ready for review.`);}
function download(){const data=page==='audit'?{demo:true,decisions:history}:{demo:true,notice:'Frontend fixtures; not solver or benchmark results.',run,metrics:{agentic:metrics(run),optimizer:metrics(run,'optimizer'),rules:metrics(run,'rules')},constraints:validate(run)};const blob=new Blob([JSON.stringify(data,null,2)],{type:'application/json'});const url=URL.createObjectURL(blob);const a=document.createElement('a');a.href=url;a.download=page==='audit'?'flowstate-decisions.json':`flowstate-${run.id}.json`;a.click();setTimeout(()=>URL.revokeObjectURL(url),500);toast('Demo report exported.');}
document.addEventListener('click',e=>{const b=e.target.closest('button,[data-action]');if(!b||b.disabled)return;const d=b.dataset;if(d.page){page=d.page;render();window.scrollTo(0,0);return;}if(d.scenario){if(running)return;config.scenario=d.scenario;render();return;}if(d.detail){detail(d.detail);return;}if(d.alternative){if(closed())return;chooseAlternative(run,d.alternative);render();review();return;}if(d.agent!==undefined){const a=agents[Number(d.agent)];openModal(`${a.name} agent`,'Specialist contract · read-only access',`<p class="rationale">${a.detail}. This agent can propose actions; only the coordinator assembles a plan and only the planner can approve it.</p><h3>Evidence source</h3><p class="rationale">${a.source} ${run.config.seed}</p><h3>Permission boundary</h3><p class="rationale">Read scoped ${a.name.toLowerCase()} data. Write structured proposals to the queue. No direct order, inventory, or shipment execution.</p><div class="notice good">Demo agent output · no model API is connected.</div>`);return;}if(d.node){const n=nodes.find(n=>n[0]===d.node);openModal(`${n[0]} · ${n[1]}`,'Network node · synthetic reference data',`<div class="notice ${n[0]==='S1'?'':'good'}">${n[2]}</div><p class="rationale">${n[0]==='S1'?'Critical supplier contributes approximately 45% of component volume. Its seven-day outage begins on day 10 and exposes SKU-01, SKU-02, and SKU-03.':n[0]==='S2'?`Qualified alternate source with ${run.scenario.capacity}% capacity available in this scenario. Current sourcing proposal: ${run.actions[0].quantity} units to P1.`:n[0][0]==='D'?'Regional distribution centre. Coverage values are illustrative snapshot data. Transfers must preserve the protected stock floor.':'Operational node in the reference network. Capacity and lead-time assumptions are fixed for reproducibility.'}</p>`);return;}
switch(d.action){case'menu':document.querySelector('.sidebar').classList.toggle('open');document.querySelector('.overlay').classList.toggle('open');break;case'close':modal.close();break;case'run':runScenario();break;case'export':download();break;case'review':review();break;case'validate':{const name=document.querySelector('#approver')?.value||'';const ok=revalidate(run);render();review();document.querySelector('#approver').value=name;toast(ok?'All demo checks passed. The plan is ready for approval.':'Validation failed. Fix the highlighted constraints.');break;}case'approve':{const name=document.querySelector('#approver')?.value;try{persist(approve(run,name));modal.close();toast('Plan approved. Your decision has been recorded.');}catch(error){toast(error.message);document.querySelector('#approver')?.focus();}break;}case'reject':{const name=document.querySelector('#approver')?.value||'';openModal('Reject recovery plan',`${run.config.scenario} · Version ${run.version}`,`<p class="rationale">Record why this plan needs another approach.</p><div class="field"><label for="reject-name">Planner name</label><input id="reject-name" value="${esc(name)}" autocomplete="name"></div><div class="field"><label for="reject-reason">Reason for rejection</label><textarea id="reject-reason" rows="3" placeholder="e.g. Alternate supplier capacity needs confirmation"></textarea></div>`,`<button class="btn" data-action="review">Back to plan</button><button class="btn danger" data-action="confirm-reject">Record rejection</button>`);break;}case'confirm-reject':{const name=document.querySelector('#reject-name').value.trim(),reason=document.querySelector('#reject-reason').value.trim();if(!name||!reason){toast('Enter your name and a reason for rejecting the plan.');return;}run.status='REJECTED';persist({id:crypto.randomUUID(),runId:run.id,version:run.version,scenario:run.config.scenario,seed:run.config.seed,decision:'REJECTED',actor:name,reason,time:new Date().toISOString(),actions:structuredClone(run.actions)});modal.close();toast('Rejection recorded. Start a new run to explore another plan.');break;}case'view-audit':modal.close();page='audit';render();break;case'alerts':case'exposure':openModal('Supplier outage · impact assessment','S1 · Apex Components · Days 10–16',`<div class="notice">High impact: 45% of component volume is exposed.</div><div class="table-scroll"><table><thead><tr><th>EXPOSED SKU</th><th>PRIMARY DC</th><th>PROJECTED STOCKOUT</th></tr></thead><tbody><tr><td>SKU-01</td><td>D1 · North</td><td>Day 13</td></tr><tr><td>SKU-02</td><td>D2 · East</td><td>Day 14</td></tr><tr><td>SKU-03</td><td>D4 · West</td><td>Day 15</td></tr></tbody></table></div><h3>Next step</h3><p class="rationale">Review the alternate sourcing, expedite, transfer, and rescheduling actions. These exposure values are demo assumptions.</p>`,`<button class="btn" data-action="close">Close</button><button class="btn primary" data-action="review">Review recovery plan ${icon('arrow')}</button>`);break;case'assumptions':openModal('Model assumptions','PRD MVP scope · synthetic frontend demo',`<p class="rationale">4 suppliers → 2 plants → 5 distribution centres. Six finished SKUs. A 60-day horizon with daily buckets. S1 shuts down on day 10 for seven days.</p><h3>Cost and capacity fixtures</h3><p class="rationale">USD is the demo currency. S2 orders use a $24 unit cost and a 100-unit minimum. Expedite actions use $8 per unit, within a $2,400 cap. P2 reserves up to 360 units. D3 has 200 transferable units. All actions use 10-unit packs.</p><h3>Document alignment</h3><p class="rationale">The PRD and architecture differ on DC count, horizon, scenario labels, and evaluation size. This frontend follows the PRD’s four scenarios and network. Architecture concepts guide the proposal, validation, and approval flow.</p><div class="notice">Metrics and confidence are deterministic illustrative fixtures. Production arithmetic, independent constraint validation, authenticated approval, and benchmarks belong in the backend.</div>`);break;case'guide':openModal('Take the control room for a spin','A five-minute hackathon walkthrough',`<ol class="rationale"><li>Choose SC1 and run the scenario with seed 42.</li><li>Inspect the disrupted supplier and agent proposals.</li><li>Open Review plan and inspect an action’s rationale.</li><li>Set alternate-source quantity to 900. Revalidate to see capacity fail and approval block.</li><li>Restore quantity to 420 and revalidate.</li><li>Enter your name and approve. Find the decision in the log.</li><li>Compare all three planners or try SC4 to see the stale-data warning.</li></ol><div class="notice good">This is an interactive frontend prototype. No live suppliers, AI calls, or order execution are connected.</div>`,`<button class="btn primary" data-action="close">Let’s explore ${icon('arrow')}</button>`);break;}
});
document.addEventListener('change',e=>{if(e.target.id==='scenario'){config.scenario=e.target.value;render();}});
document.addEventListener('input',e=>{
 if(['seed','lab-seed'].includes(e.target.id))config.seed=e.target.value;
 if(e.target.dataset.quantity){
  editQuantity(run,e.target.dataset.quantity,e.target.value);
  const approval=modal.querySelector('[data-action=approve]');if(approval)approval.disabled=true;
  const checks=validate(run);
  const panel=modal.querySelector('.checks');if(panel)panel.innerHTML=checks.map(c=>`<div class="constraint ${c.pass?'':'fail'}">${icon(c.pass?'circlecheck':'alert')}<div>${c.name}<small>${c.detail}</small></div></div>`).join('');
  const subtitle=modal.querySelector('.modal-head p');if(subtitle)subtitle.textContent=`${run.config.scenario} · Seed ${run.config.seed} · Version ${run.version} · Needs validation`;
  const heading=panel?.previousElementSibling;if(heading)heading.innerHTML=`Constraint validation <span class="tag ${checks.every(c=>c.pass)?'green':'red'}">${checks.filter(c=>c.pass).length} / ${checks.length} passed</span>`;
  if(!modal.querySelector('.edit-notice')){const notice=document.createElement('div');notice.className='notice edit-notice';notice.textContent='Quantities changed. Revalidate to refresh the plan estimates and enable approval.';panel?.before(notice);}
 }
});
modal.addEventListener('click',e=>{if(e.target===modal){const r=modal.getBoundingClientRect();if(e.clientX<r.left||e.clientX>r.right||e.clientY<r.top||e.clientY>r.bottom)modal.close();}});
window.addEventListener('hashchange',()=>{if(location.hash==='#overview'){page='overview';render();}});
let preferences={name:'Demo planner',reduceMotion:false};
try{const saved=JSON.parse(localStorage.getItem('flowstate-preferences')||'null');if(saved&&typeof saved.name==='string'&&saved.name.trim())preferences={name:saved.name.trim().slice(0,60),reduceMotion:saved.reduceMotion===true};}catch{}
function showSettings(){
 openModal('Settings','Your Flowstate workspace',`<form id="account-settings-form"><div class="field"><label for="display-name">Display name</label><input id="display-name" name="displayName" value="${esc(preferences.name)}" required maxlength="60" autocomplete="nickname"><small>Shown in your sidebar. This is a local demo profile.</small></div><label class="settings-toggle"><input type="checkbox" name="reduceMotion" ${preferences.reduceMotion?'checked':''}><span><strong>Reduce motion</strong><small>Turn off animated gradients and interface transitions.</small></span></label><div class="notice good">Preferences are saved in this browser. Signing out ends your demo session and keeps your decision history.</div></form>`,`<button class="btn danger" data-action="sign-out">Sign out</button><div class="btn-group"><button class="btn" data-action="close">Cancel</button><button class="btn primary" type="submit" form="account-settings-form">Save changes</button></div>`);
}
document.addEventListener('click',e=>{
 const action=e.target.closest('[data-action]')?.dataset.action;
 if(!authenticated)return;
 if(action==='account-settings')showSettings();
 if(action==='sign-out'){
  try{sessionStorage.removeItem('flowstate-authenticated');}catch{}
  authenticated=false;authMode='signin';page='overview';
  if(modal.open)modal.close();
  render();window.scrollTo(0,0);toast('You have signed out of Flowstate.');
 }
});
document.addEventListener('submit',e=>{
 if(e.target.id!=='account-settings-form')return;
 e.preventDefault();if(!authenticated)return;
 const data=new FormData(e.target),name=String(data.get('displayName')||'').trim();
 if(!name){toast('Enter a display name.');return;}
 preferences={name:name.slice(0,60),reduceMotion:data.get('reduceMotion')==='on'};
 let stored=true;try{localStorage.setItem('flowstate-preferences',JSON.stringify(preferences));}catch{stored=false;}
 modal.close();render();toast(stored?'Settings saved.':'Settings applied for this session; browser storage is unavailable.');
});
render();
document.addEventListener('submit',e=>{if(e.target.id!=='auth-form')return;e.preventDefault();const data=new FormData(e.target);const email=String(data.get('email')||'').trim();const password=String(data.get('password')||'');const terms=data.get('terms');if(authMode==='signup'&&!terms){toast('Please accept the Terms and Services to continue.');return;}if(!email||!password){toast('Enter your email and password to continue.');return;}authenticated=true;try{sessionStorage.setItem('flowstate-authenticated','true')}catch{}render();toast(authMode==='signup'?'Welcome to flowstate.':'Signed in to flowstate.');});
document.addEventListener('click',e=>{const b=e.target.closest('button,[data-action]');if(!b||authenticated)return;const d=b.dataset;if(d.action==='auth-toggle'){authMode=authMode==='signup'?'signin':'signup';render();}if(d.action==='auth-google'||d.action==='auth-apple'){authenticated=true;try{sessionStorage.setItem('flowstate-authenticated','true')}catch{}render();toast('Welcome to flowstate.');}if(d.action==='terms'||d.action==='privacy'){e.preventDefault();openModal(d.action==='terms'?'Terms and Services':'Privacy Policy','flowstate demo account',`<p class="rationale">This prototype keeps the sign-up language visible for the demo. No legal agreement is submitted, no external account is created, and no personal data is sent anywhere.</p>`,'<button class="btn primary" data-action="close">Close</button>');}});
